import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2020-10-29","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-10-29","date":"2020-10-29T00:00:00.000Z","updated":"2020-11-03T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","自动缩放","内存管理","缓存策略"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-10-29.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-10-29.md","lastUpdated":1780460162000}'),n={name:"posts/2020/Ceph_Performance_Meeting_2020-10-29.md"};function i(l,e,s,g,h,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>在2020年10月29日的Ceph性能会议上，团队讨论了多个关键的性能改进和开发更新。以下是会议的主要内容和决定事项：</p><h3 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h3><ul><li><strong>性能改进PR</strong>：Jason审查了异步创建镜像快照和RBD异步的性能改进PR，并讨论了集成AVX擦除编码的构建变更。</li><li><strong>BlueStore动态层级PR</strong>：Adam的工作与该PR不兼容，需要进一步审查。</li><li><strong>缓存分桶代码</strong>：大部分代码已合并，剩余部分正在单独分支中处理。</li><li><strong>PG自动缩放讨论</strong>：讨论了改进算法以改善初始安装时的性能，提出通过调整PG日志长度来控制内存使用。</li><li><strong>内存使用和缓存年龄分桶</strong>：Adam修复了数据缓存的bug，并讨论了内存管理和内存碎片化问题。</li><li><strong>I/O环讨论</strong>：在Kernel 5.9上构建包含liburing支持的Ceph代码时遇到构建问题，初步测试未见性能差异。</li></ul><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li><strong>PG自动缩放算法改进</strong>：同意改进PG自动缩放算法，以避免频繁的数据移动和优化并发性能。</li><li><strong>内存管理和缓存优化</strong>：确认了内存碎片化问题，并讨论了可能的解决方案。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li><strong>PG自动缩放算法实现</strong>：继续开发和测试新的PG自动缩放算法。</li><li><strong>内存碎片化问题解决</strong>：进一步研究和测试内存碎片化解决方案。</li><li><strong>I/O环性能测试</strong>：继续验证liburing在Ceph中的正确使用，并进行更深入的性能测试。</li><li><strong>下周议程</strong>：将PG日志相关讨论作为下周会议的首要议题。</li></ul><p>会议强调了Ceph性能优化的重要性，并确定了多个关键项目，以进一步提高Ceph的稳定性和性能。</p>',9)])])}const c=t(n,[["render",i]]);export{d as __pageData,c as default};
